using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.UpperGap;
internal sealed class EndpointDocument : IScribeDocumentDefinition
{
 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
  "Physical construction on the upper-gap boundary",
  H("One physical permutation, two actual centered rows, one literal ear"),
  Blocks(
   Paragraph(Text("Let a,b,c,d>=2, k=a+b+c+d, A=1+2^a+2^(a+b)+2^(a+b+c), N=2^k-1 and Q=2N+1. The intended upper-gap conclusion quantifies every d>max(a,b,c): there must exist one permutation sigma of the original physical labels and one natural j<=k such that OriginalOrder(k,A,sigma) and OriginalOrder(k+1,2A,earWord(k,sigma,j)) both hold. Each OriginalOrder includes its exact zero total and every natural take-prefix, including empty, full and overlong prefixes. This source preparation does not yet contain that final theorem. Its helpers are uncompiled and carry no kernel or route acceptance claim.")),
   Paragraph(Text("The existing full MaxPlusTwo.Endpoint handles d>=max(a,b,c)+2 with literal cut zero. The remaining layer is d=max(a,b,c)+1. It splits exhaustively into weak peak b>=max(a,c); strict first maximum a>max(b,c); tied outer maximum a=c>b; and strict third maximum c>max(a,b). The last case separates a<b, b<a and a=b. These are direct constructions at the original source coordinates; swapping parameters or rotating gaps is not used.")),
   Paragraph(Text("Write x=2^a,y=2^b,z=2^c,t=2^d, C=xy+x+1, B=tC+1, L=tz(x+1)+z+1, M=tyz+yz+y+1 and D=yz+y+1. SourceTable and PacketNormalForm.Source supply the exact original chains U_i=i, V_i=d+i, W_i=d+c+i and X_i=d+c+b+i, of lengths d,c,b,a. Their old heads are A,B,L,M and new heads 2A,Bp=2B-1,Lp=2L-z-1,Mp=2M-D. The four old successors are B,L,M,A; the new successors are Bp,Lp,Mp,A. The last new successor is A. Label k has actual new value A. All occurrences remain separate even when their numerical values agree.")),
   Paragraph(Text("A binary mask denotes the actual positions of a positive chain. The existing increasing decoder, nested-mask partition and exact weighted-mass theorem are reused. In the common U,V,W,X terminal order, take masks u,r,p,q,w with r contained in u and q contained in p. The positive bags are U outside u; U in u minus r together with V outside p; U in r together with V in p minus q and W outside w; and V in q together with W in w and all X positives. The implementation expresses contained masks as physical intersections. The remaining dyadic allocation proof must show that these intersections equal their displayed smaller masks on the stated chamber.")),
   Paragraph(Text("For the weak peak set n=1 when a=b=c, otherwise n=2 floor((B-1)/(2A)); put u=n-1, r=1 when a<c and zero otherwise, p=q=0. Set w=0 when a=b, w=1 when b=a+1, and otherwise w=ceil((M+1-2A)/(2L)). The three nonfinal old seams are B-nA, L-(r+1)A and M-A-wL. The new seams are Bp-2nA, Lp-2(r+1)A and Mp-2A-wLp. The native n=1 branch and the w=0 branch retain all equality faces.")),
   Paragraph(Text("For a>max(b,c), when b<c set n=2 floor((B-1)/(2A)), u=n-1, r=0 and p=2^(c-b-1). When b>=c put h=2^(a-b), n=h floor((B-1)/(hA)), u=n-1, r=h-1 and p=0. In both cases q=w=0. These are the caller's piecewise masks. The separate Pro maximal-subcube construction was read as an alternative but is not used here. For a=c>b the masks are u=r=1, p=2^(a-b-1)-1, q=w=0; the all-equal face already belongs to the weak peak.")),
   Paragraph(Text("For a<b<c put u=1,r=0,p=2^(c-b)-1,q=0,w=2^(b-a-1). Thus U_0 goes to the V bag, the low c-b V positions go to W, and the single W position b-a-1 goes to X. For b<a<c put u=r=1,p=2^(c-b-1)-1,q=2^(c-a-1),w=0. Here U_0 and the low V positions except the q singleton go to W, while that singleton goes to X. Both constructions are at the literal supplied physical offsets.")),
   Paragraph(Text("For a=b=u<c change the terminal order to U,W,V,X. Let q=2^(c-u-1); put p=0 for c<2u and p=2^(c-2u) for c>=2u. The p and q physical singleton positions are distinct in the large case. Use the existing masked blocks with masks (1,1,0,0,p OR q,q,0), then interchange their second and third complete bag-terminal blocks. Thus U_0 and the p singleton accompany the W positives; the q singleton accompanies X; all remaining V positives accompany the V terminal. This reuses the same physical inventory theorem. It does not assume the separately owned formalization has compiled.")),
   Paragraph(Text("Every boundary word ends with X_(a-1)=k-1. Its literal fresh cut is j=k-1. The two strict-third constructions, tied-outer construction, all-equal face, and the small and large equal-first charts each have explicit source drafts for all sixteen seam and peak margins. The weak-peak and strict-first drafts supply the remaining polynomial signs, capacities and rounding buffers. The nineteen charts are unbounded. Each drafted sign proof states an exact rational polynomial identity and proves nonnegativity of its coefficients by ordinary Lean arithmetic; finite controls are not premises.")),
   Paragraph(Text("For an old seam S with successor R the old peak condition is 2S<=R-1. For a new seam T with successor Rprime the new peak condition is 2T<=Rprime-1. Positivity of every bag step and negativity of each terminal turn these into all-prefix bounds through the existing packet theorem. The new fourth bag includes the actual fresh A, and both final seams are zero. The drafted packet bridge consumes explicit physical lists and their packet checks, then uses the existing actual-source and finite-certificate equivalences. It assumes no Certificate existence.")),
   Paragraph(Text("The remaining formal work is to instantiate the charts at the actual dyadic powers, prove the contained-mask equalities and capacities for the selected integer formulas, derive the actual packet checks from the paired source masses and terminals, and assemble the one upper-gap endpoint with the full MaxPlusTwo theorem. A final typed theorem description and faithful Reg registration belong to that endpoint once it exists. The present narrative does not describe a completed endpoint, and unrestricted physical J remains open."))
  ),[]));
}
